const b = $input.first().json.body ?? $input.first().json;

const missing = ['pipeline_id', 'ref', 'status'].filter(k => b[k] === undefined);
if (missing.length) throw new Error('Invalid payload, missing: ' + missing.join(', '));

const ref = String(b.ref);
const isRelease = ref.startsWith('release/');

return [{
  json: {
    pipeline_id: Number(b.pipeline_id),
    project: b.project ?? 'unknown',
    ref,
    status: b.status,
    triggered_by: b.triggered_by ?? 'unknown',
    web_url: b.web_url ?? '',
    severity: isRelease ? 'high' : 'medium',
    relevant: b.status === 'failed' && (ref === 'main' || isRelease),
    received_at: new Date().toISOString()
  }
}];

const p = $('Normalize payload').first().json;
const analysis = $json.output;

const md = `# Triage: pipeline ${p.pipeline_id}

- Project: ${p.project}
- Branch: ${p.ref}
- Severity: ${p.severity}
- Triggered by: ${p.triggered_by}
- Received: ${p.received_at}
- Link: ${p.web_url}

---

${analysis}

---
_Generated by CI Failure Triage Bot (qwen2.5:7b via Ollama)_
`;

return [{ json: { pipeline_id: p.pipeline_id, ref: p.ref, severity: p.severity, report: md } }];

